import Component from 'flarum/common/Component';
import { t } from '../../common/t';
import { frame, samplePost } from './Sample';
/** What a guest who has used up their free discussions sees, live. */
export default class MeterPreview extends Component {
  view() {
    const limit = Math.max(1, parseInt(this.attrs.limit(), 10) || 5);
    const leadIn = Math.max(0, parseInt(this.attrs.leadIn(), 10) || 0);
    const period = ['day', 'week', 'month'].includes(this.attrs.period()) ? this.attrs.period() : 'month';
    const meter = {
      limit,
      remaining: 0,
      counted: false,
      warn: 0,
      period
    };
    return m("div", {
      className: "Form-group"
    }, frame(t('admin.preview.title_meter'), [samplePost({
      number: 1,
      gate: {
        mode: leadIn > 0 ? 'lead' : 'hide',
        reason: 'meter'
      },
      locked: [],
      chars: leadIn,
      meter
    }), samplePost({
      number: 2,
      gate: {
        mode: 'hide',
        reason: 'meter'
      },
      locked: [],
      compact: true
    })]));
  }
}
flarum.reg.add('ernestdefoe-guest-gate', 'admin/components/MeterPreview', MeterPreview);